namespace Sistem\Model;

class Siswa
{
    public function __construct(
        public int $id,
        public string $nim,
        public string $nama,
        public string $email,
        public string $jurusan,
    ) {}

    public static function dariArray(array $data): static
    {
        return new static(
            (int) ($data["id"] ?? 0),
            (string) ($data["nim"] ?? ""),
            (string) ($data["nama"] ?? ""),
            (string) ($data["email"] ?? ""),
            (string) ($data["jurusan"] ?? ""),
        );
    }

    public function keArray(): array
    {
        return [
            "id" =&gt; $this-&gt;id,
            "nim" =&gt; $this-&gt;nim,
            "nama" =&gt; $this-&gt;nama,
            "email" =&gt; $this-&gt;email,
            "jurusan" =&gt; $this-&gt;jurusan,
        ];
    }
}
