namespace Sistem\Repository;

use RuntimeException;
use Sistem\Model\Siswa;

class SiswaRepository
{
    public function __construct(private string $berkas) {}

    /**
     * @return Siswa[]
     */
    public function semua(): array
    {
        $daftar = array_map(
            fn (array $baris) =&gt; Siswa::dariArray($baris),
            $this-&gt;baca()
        );

        usort($daftar, fn (Siswa $a, Siswa $b) =&gt; strcasecmp($a-&gt;nama, $b-&gt;nama));

        return $daftar;
    }

    public function cari(int $id): ?Siswa
    {
        foreach ($this-&gt;baca() as $baris) {
            if ((int) $baris["id"] === $id) {
                return Siswa::dariArray($baris);
            }
        }

        return null;
    }

    public function cariNim(string $nim): ?Siswa
    {
        foreach ($this-&gt;baca() as $baris) {
            if ((string) $baris["nim"] === $nim) {
                return Siswa::dariArray($baris);
            }
        }

        return null;
    }

    public function simpan(Siswa $siswa): Siswa
    {
        $data = $this-&gt;baca();

        if ($siswa-&gt;id === 0) {
            $siswa-&gt;id = $this-&gt;idBerikutnya($data);
            $data[] = $siswa-&gt;keArray();
        } else {
            foreach ($data as $indeks =&gt; $baris) {
                if ((int) $baris["id"] === $siswa-&gt;id) {
                    $data[$indeks] = $siswa-&gt;keArray();
                }
            }
        }

        $this-&gt;tulis($data);

        return $siswa;
    }

    public function hapus(int $id): bool
    {
        $data = $this-&gt;baca();
        $sisa = array_values(array_filter(
            $data,
            fn (array $baris) =&gt; (int) $baris["id"] !== $id
        ));

        if (count($sisa) === count($data)) {
            return false;
        }

        $this-&gt;tulis($sisa);

        return true;
    }

    private function baca(): array
    {
        if (!is_file($this-&gt;berkas)) {
            return [];
        }

        $isi = file_get_contents($this-&gt;berkas);

        if ($isi === false || trim($isi) === "") {
            return [];
        }

        $data = json_decode($isi, true);

        if (!is_array($data)) {
            throw new RuntimeException("Berkas data rusak: " . basename($this-&gt;berkas));
        }

        return $data;
    }

    private function tulis(array $data): void
    {
        $folder = dirname($this-&gt;berkas);

        if (!is_dir($folder)) {
            mkdir($folder, 0775, true);
        }

        $json = json_encode(array_values($data), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE);

        if ($json === false || file_put_contents($this-&gt;berkas, $json, LOCK_EX) === false) {
            throw new RuntimeException("Gagal menulis berkas data.");
        }
    }

    private function idBerikutnya(array $data): int
    {
        $daftarId = array_map(fn (array $baris) =&gt; (int) $baris["id"], $data);

        return $daftarId === [] ? 1 : max($daftarId) + 1;
    }
}
</code></pre> Method Penjelasan <code>semua()</code> Mengubah setiap baris menjadi objek <code>Siswa</code>, lalu mengurutkan menurut nama (tanpa membedakan huruf besar-kecil). <code>cari($id)</code> / <code>cariNim($nim)</code> Mengembalikan <code>Siswa</code> atau <code>null</code> bila tidak ada (tipe <code>?Siswa</code>). <code>simpan($siswa)</code> Jika <code>id === 0</code> berarti data baru: beri ID berikutnya dan tambahkan. Jika tidak, ganti baris yang ID-nya sama. <code>hapus($id)</code> Menyaring baris dengan ID itu; mengembalikan <code>false</code> bila tidak ada yang dihapus. <code>baca()</code> Membaca berkas; kosong atau belum ada dianggap <code>[]</code>; JSON rusak melempar <code>RuntimeException</code>. <code>tulis()</code> Membuat folder bila perlu, menulis JSON, dan melempar exception bila gagal. <code>LOCK_EX</code> mengunci berkas saat menulis. <code>idBerikutnya()</code> ID terbesar saat ini ditambah 1. <p>Method <code>baca</code>, <code>tulis</code>, dan <code>idBerikutnya</code> bersifat <code>private</code> karena hanya urusan internal (enkapsulasi). Pemanggil cukup tahu <code>semua</code>, <code>cari</code>, <code>simpan</code>, dan <code>hapus</code>.</p>

